```
{
  inputs = {
    nixpkgs.url = "nixpkgs";
    utils.url = "github:numtide/flake-utils";
  };

  outputs =
    {
      self,
      nixpkgs,
      utils,
    }:
    utils.lib.eachDefaultSystem (
      system:
      let
        pkgs = nixpkgs.legacyPackages.${system};
      in
      {
        packages.default = pkgs.callPackage ./default.nix { };
        apps.default = {
          type = "app";
          program = "${self.packages.${system}.default}/bin/hello";
        };
        devShells.default = pkgs.mkShell {
          buildInputs = [
            pkgs.x10
            pkgs.futhark
            pkgs.gfortran
            pkgs.gforth
            pkgs.hvm
          ];
        };
      }
    );
}
```

```
{ stdenv, x10, futhark, gfortran, gforth, hvm }:
stdenv.mkDerivation {
  pname = "hello";
  version = "0.0.1";
  phases = [ "installPhase" ];
  installPhase = ''
    mkdir -p $out/bin
    cat > $out/bin/hello <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
export PATH="${x10}/bin:${futhark}/bin:${gfortran}/bin:${gforth}/bin:${hvm}/bin:$PATH"
echo "x10"
if command -v x10c >/dev/null 2>&1; then x10c -version || true; elif command -v x10 >/dev/null 2>&1; then x10 -help >/dev/null 2>&1 || true; fi
echo "futhark"
futhark --version
echo "gfortran"
gfortran --version | head -n1
echo "gforth"
gforth --version
echo "hvm"
hvm --version
EOF
    chmod +x $out/bin/hello
  '';
}
```
